flutter_main:
import 'package:flutter/material.dart';
import 'package:camera_flutter/camera_flutter.dart';
Future<void> main() async { WidgetsFlutterBinding.ensureInitialized(); final backend = await CameraControlFlutter.ensureInitialized(); runApp(MaterialApp(home: Text(backend))); }

dart_main:
import 'dart:ffi';
import 'dart:io';
import 'package:camera_dart/camera_dart.dart';
Future<void> main() async { DynamicLibrary.open(Platform.environment['CAMERA_CLI_LIBRARY']!); CameraControl.ensureInitialized(); if (CameraBackendRegistry.instance.selected.name != 'ffi') { throw StateError('native camera backend did not load'); } final cameras = await CameraControl.enumerate(); print('FFI loaded; enumerated ${cameras.length} camera devices'); await CameraBackendRegistry.instance.selected.dispose(); }
